    pub fn color_slash_opacity_op_absent(
        key: &str,
        base: &str,
        opacity: &str,
        important: Option<&'static str>,
        op: Option<&str>,
    ) -> (DiagnosticCode, Args) {
        debug_assert!(important.is_none_or(|v| ["!"].contains(&v)));
        (
            DiagnosticCode::ColorSlashOpacity,
            Args::default()
                .text("form", "op-absent")
                .text("key", key)
                .text("base", base)
                .text("opacity", opacity)
                .optional_text("important", important)
                .optional_text("op", op),
        )
    }
